solution.solution.cpp:
#include <cctype>
#include <string>

namespace
{
    std::string lower(std::string s) { for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return s; }
    bool startsWithI(const std::string& s, const std::string& prefix) { return s.size() >= prefix.size() && lower(s.substr(0, prefix.size())) == lower(prefix); }
    bool isDrive(const std::string& s) { return s.size() >= 3 && std::isalpha(static_cast<unsigned char>(s[0])) && s[1] == ':' && s[2] == '\\'; }
}

bool validBaseName(const std::string& base)
{
    if (base.empty() || base.size() > 32 || !std::isalpha(static_cast<unsigned char>(base[0]))) return false;
    for (char c : base) if (!std::isalnum(static_cast<unsigned char>(c))) return false;
    return true;
}

std::string deviceName(const std::string& base) { return validBaseName(base) ? "\\Device\\" + base : ""; }
std::string linkName(const std::string& base) { return validBaseName(base) ? "\\??\\" + base : ""; }
std::string userPath(const std::string& base) { return validBaseName(base) ? "\\\\.\\" + base : ""; }

std::string win32ToNt(const std::string& p)
{
    if (isDrive(p)) return "\\??\\" + p;
    if (startsWithI(p, "\\\\?\\UNC\\")) return "\\??\\UNC\\" + p.substr(8);
    if (p.rfind("\\\\?\\", 0) == 0) return isDrive(p.substr(4)) ? "\\??\\" + p.substr(4) : "";
    if (p.rfind("\\\\.\\", 0) == 0) return p.size() > 4 ? "\\??\\" + p.substr(4) : "";
    if (p.rfind("\\\\", 0) == 0 && p.size() > 2) return "\\??\\UNC\\" + p.substr(2);
    return "";
}

std::string ntToWin32(const std::string& nt)
{
    std::string rest;
    if (nt.rfind("\\??\\", 0) == 0) rest = nt.substr(4);
    else if (startsWithI(nt, "\\DosDevices\\")) rest = nt.substr(12);
    else if (startsWithI(nt, "\\Device\\")) return "\\\\?\\GLOBALROOT" + nt;
    else return "";
    if (rest.empty()) return "";
    if (startsWithI(rest, "UNC\\")) return "\\\\" + rest.substr(4);
    if (isDrive(rest)) return rest;
    return "\\\\.\\" + rest;
}

std::string serviceName(const std::string& path)
{
    const std::string head{ "\\REGISTRY\\MACHINE\\SYSTEM\\" };
    if (!startsWithI(path, head)) return "";
    std::string rest{ path.substr(head.size()) };
    if (startsWithI(rest, "CurrentControlSet\\")) rest = rest.substr(18);
    else if (startsWithI(rest, "ControlSet") && rest.size() > 14 && std::isdigit(static_cast<unsigned char>(rest[10])) &&
             std::isdigit(static_cast<unsigned char>(rest[11])) && std::isdigit(static_cast<unsigned char>(rest[12])) && rest[13] == '\\')
        rest = rest.substr(14);
    else return "";
    if (!startsWithI(rest, "Services\\")) return "";
    const std::string name{ rest.substr(9) };
    if (name.empty() || name.find('\\') != std::string::npos) return "";
    return name;
}

std::string userRegistryPath(const std::string& path)
{
    if (startsWithI(path, "\\REGISTRY\\MACHINE\\")) return "HKEY_LOCAL_MACHINE\\" + path.substr(18);
    if (startsWithI(path, "\\REGISTRY\\USER\\")) return "HKEY_USERS\\" + path.substr(15);
    return "";
}

unitTests:
TEST("base names") {
    CHECK(validBaseName("XenonEcho")); CHECK(validBaseName("A1")); CHECK(!validBaseName("")); CHECK(!validBaseName("1Xenon")); CHECK(!validBaseName("Xenon Echo")); CHECK(!validBaseName(std::string(33, 'a'))); CHECK(validBaseName(std::string(32, 'a')));
    CHECK_EQ(deviceName("XenonEcho"), std::string("\\Device\\XenonEcho")); CHECK_EQ(linkName("XenonEcho"), std::string("\\??\\XenonEcho")); CHECK_EQ(userPath("XenonEcho"), std::string("\\\\.\\XenonEcho")); CHECK_EQ(deviceName("bad name"), std::string(""));
}
TEST("Win32 to NT") {
    CHECK_EQ(win32ToNt("C:\\Notes\\a.txt"), std::string("\\??\\C:\\Notes\\a.txt")); CHECK_EQ(win32ToNt("\\\\srv\\docs\\a"), std::string("\\??\\UNC\\srv\\docs\\a"));
    CHECK_EQ(win32ToNt("\\\\.\\XenonEcho"), std::string("\\??\\XenonEcho")); CHECK_EQ(win32ToNt("\\\\?\\C:\\long"), std::string("\\??\\C:\\long")); CHECK_EQ(win32ToNt("\\\\?\\UNC\\srv\\x"), std::string("\\??\\UNC\\srv\\x"));
    CHECK_EQ(win32ToNt("notes.txt"), std::string("")); CHECK_EQ(win32ToNt("C:notes"), std::string("")); CHECK_EQ(win32ToNt("\\Windows"), std::string(""));
}
TEST("NT to Win32") {
    CHECK_EQ(ntToWin32("\\??\\C:\\Notes"), std::string("C:\\Notes")); CHECK_EQ(ntToWin32("\\??\\UNC\\srv\\docs"), std::string("\\\\srv\\docs")); CHECK_EQ(ntToWin32("\\??\\XenonEcho"), std::string("\\\\.\\XenonEcho"));
    CHECK_EQ(ntToWin32("\\DosDevices\\C:\\x"), std::string("C:\\x")); CHECK_EQ(ntToWin32("\\dosdevices\\XenonEcho"), std::string("\\\\.\\XenonEcho"));
    CHECK_EQ(ntToWin32("\\Device\\HarddiskVolume3\\x"), std::string("\\\\?\\GLOBALROOT\\Device\\HarddiskVolume3\\x")); CHECK_EQ(ntToWin32("\\Registry\\Machine"), std::string(""));
    for (const char* p : { "C:\\a\\b", "\\\\srv\\share\\f", "\\\\.\\XenonEcho" }) CHECK_EQ(ntToWin32(win32ToNt(p)), std::string(p));
}
TEST("registry paths") {
    CHECK_EQ(serviceName("\\REGISTRY\\MACHINE\\SYSTEM\\CurrentControlSet\\Services\\XenonHello"), std::string("XenonHello"));
    CHECK_EQ(serviceName("\\Registry\\Machine\\System\\ControlSet001\\services\\XenonLog"), std::string("XenonLog"));
    CHECK_EQ(serviceName("\\REGISTRY\\MACHINE\\SYSTEM\\ControlSet1\\Services\\X"), std::string("")); CHECK_EQ(serviceName("\\REGISTRY\\MACHINE\\SYSTEM\\CurrentControlSet\\Services\\X\\Parameters"), std::string(""));
    CHECK_EQ(userRegistryPath("\\Registry\\Machine\\SYSTEM\\CurrentControlSet\\Services\\XenonHello"), std::string("HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Services\\XenonHello"));
    CHECK_EQ(userRegistryPath("\\REGISTRY\\USER\\S-1-5-21-1\\Software"), std::string("HKEY_USERS\\S-1-5-21-1\\Software")); CHECK_EQ(userRegistryPath("HKLM\\x"), std::string(""));
}

